# categories whose concepts are not photographs: the prompt templates differ
NOT_PHOTO = {"art and pattern", "microscopic and cosmic", "textures", "fantasy and sci-fi", "painting and drawing", "illustration and graphic design", "paper and lettering"}
TEMPLATES = ["a photo of {}", "a detailed close-up photo of {}", "a painting of {}"]
TEMPLATES_NOT_PHOTO = ["{}", "{}, detailed", "{}, artwork"]


def all_concepts():
    """[(category, subject)] in a fixed order."""
    return [(c, s) for c, items in CONCEPTS.items() for s in items]


def prompt(category, subject, style):
    return (TEMPLATES_NOT_PHOTO if category in NOT_PHOTO else TEMPLATES)[style].format(subject)
